For integers $i, j$ we write $\range ij = \set{i, i+1, \dots, j-1}$ and $\rangezero j = \range 0j$. Moreover, we set $\poly(n) = n^{\Order(1)}$, $\polylog(n) = (\log n)^{\Order(1)}$ and  $\widetilde\Order(n) = n \polylog(n)$.

\paragraph{Strings}
We usually denote strings by capital letters $X, Y, Z$. The length of a string $X$ is denoted by $|X|$ and we write $X \circ Y$ to denote the \emph{concatenation} of $X$ and $Y$. For a nonnegative integer $i$, we denote by~$X \access i$ the $i$-th character in $X$ (starting with index zero). For integers $i, j$ we denote by $X \range ij$ the substring of $X$ with indices in $\range ij$. In particular, if the indices are out-of-bounds, then we set $X \range ij = X \range{\max(i, 0)}{\min(j, |X|)}$.

For two strings $X, Y$ with equal length, $X$ is a \emph{rotation} of $Y$ if $X \access i = Y \access{(i + s) \bmod |Y|}$ for some integer shift $s$. We say that $X$ is \emph{primitive} if all of the nontrivial rotations of $X$ are not equal to $X$. For a string $P$, we denote by $P^*$ the infinite-length string obtained by repeating $P$. We say that $X$ is \emph{periodic with period $P$} if $X = P^* \range{0}{|X|}$. We also say that~$X$ is \emph{$p$-periodic} if it is periodic with some period of length at most~$p$.

\paragraph{Hamming and Edit Distance}
For two equal-length strings $X, Y$, we define their \emph{Hamming distance $\HD(X, Y)$} as the number of non-equal characters: $\HD(X, Y) = |\{\, i : X \access i \neq Y \access i \,\}|$. For two strings~$X, Y$ (with possibly different lengths), we define their \emph{edit distance $\ED(X, Y)$} as the smallest number of edit operations necessary to transform $X$ into $Y$; here, an edit operation means \emph{inserting}, \emph{deleting} or \emph{substituting} a character.

\paragraph{Trees}
In the following we will implicitly refer to trees $T$ where each node has an ordered list of children. A node is a \emph{leaf} if it has no children and otherwise an \emph{internal} node. The \emph{depth} of a node $v$ is defined as the number of
ancestors of $v$, and the depth of a tree $T$ is the length of the longest root-leaf path. We refer to the subset of nodes with depth $i$ as the \emph{$i$-th level} in $T$.

\paragraph{Approximations}
We often deal with additive \emph{and} multiplicative approximations in this paper. To simplify the notation, we say that $\widetilde x$ is a $(a, b)$-approximation of $x$ whenever $x/a - b \leq \widetilde x \leq a x + b$.

\begin{definition}[Partition Tree] \label{def:partition-tree}
Let $T$ be a tree where each node $v$ is labeled with a non-empty interval $I_v$. We call $T$ a \emph{partition tree} if
\begin{itemize}
\item for the root node $v$ we have $I_v = \rangezero n$, and
\item for any node $v$ with children $v_0, \dots, v_{B-1}$, $I_v$ is the concatenation of $I_{v_0}, \dots, I_{v_{B-1}}$. 
\end{itemize}
\end{definition}

\begin{definition}[Capped Edit Distance] \label{def:capped-ed}
For strings $X, Y$ and $K \geq 0$, we define the \emph{$K$-capped edit distance $\ED^{\leq K}(X, Y) = \min(\ED(X, Y), K)$}.
\end{definition}

\begin{definition}[Capped Tree Distance] \label{def:capped-td}
Let $X, Y$ be strings, let $K \geq 0$ and let $T$ be a partition tree. For any node $v$ in $T$ and any shift $s \in \set{-K, \dots, K}$, we define the \emph{$K$-capped tree distance $\TD^{\leq K}_{v, s}(X, Y)$} as follows:
\begin{itemize}
    \item If $v$ is an a leaf with $I_v = \range ij$, then $\TD_{v, s}^{\leq K}(X, Y) = \ED^{\leq K}(X \range ij, Y \range{i + s}{j + s})$.
    \item If $v$ is an internal node with children $v_0, \dots, v_{B-1}$, then
    \begin{equation} \label{eq:capped-td}
        \TD_{v, s}^{\leq K}(X, Y) = \min\left(\sum_{i \in \rangezero B} \min_{-K \leq s' \leq K} (\TD_{v_i, s'}^{\leq K}(X, Y) + 2 \cdot |s - s'|), K \right)\!.
    \end{equation}
\end{itemize}
We write $\TD_T^{\leq K}(X, Y) = \TD_{v, 0}^{\leq K}(X, Y)$ where $v$ is the root node in $T$, and we omit the subscript $T$ when it is clear from the context.
\end{definition}

Let us first introduce the following notational shortcuts:
\begin{itemize}
\item $X_v = X \range ij$ (the substring of $X$ relevant at $v$), 
\item $Y_{v, s} = Y \range{i + s}{j + s}$ (the substring of $Y$ relevant at $v$ for one specific shift $s$),
\item $Y_v = Y \range{i - K}{j + K}$ (the entire substring of $Y$ relevant at $v$).
\end{itemize}
Moreover, for each node $v$ in the partition tree we also define:
\begin{itemize}
\item A \emph{rate} (or \emph{additive accuracy}) $r_v$. This parameter serves two purposes. First, it gives a budget for the number of characters that can be read at $v$ (i.e., we are allowed to read~$r_v |X_v|$ symbols). Second, it determines the \emph{additive} approximation guarantee at $v$, in the sense that the output at $v$ is allowed to have additive error $1/r_v$. For the root node we set $r_v = 1000 / K$.
\item The \emph{multiplicative accuracy $\alpha_v > 1$.} This parameter determines the multiplicative approximation ratio at $v$. For the root node we set $\alpha_v = 10$.
\end{itemize}

\begin{definition}[Tree Distance Problem] \label{def:problem}
Given a node $v$ in the partition tree $T$, compute a list of numbers $\Delta_{v, -K}, \dots, \Delta_{v, K}$ such that
\begin{equation} \label{eq:delta-approx}
    \frac1{\alpha_v} \ED^{\leq K}(X_v, Y_{v, s}) - \frac1{r_v} \leq \Delta_{v, s} \leq \alpha_v \TD^{\leq K}_{v, s}(X, Y) + \frac1{r_v}.
\end{equation}
\end{definition}

\begin{restatable}[Precision Sampling Lemma]{lemma}{lempsl}\label{lem:precision-sampling}
Let $\varepsilon, \delta > 0$. There is a distribution $\mathcal D = \mathcal D(\varepsilon, \delta)$ supported over the real interval $(0,1]$ with the following properties:
\begin{itemize}
\itemdesc{Accuracy:} Let $A_1, \dots, A_n \in \Real$ and let $u_1, \dots, u_n \sim {\cal D}$ be sampled independently. There is a recovery algorithm with the following guarantee: Given $(a, b \cdot u_i)$\=/approximations~$\widetilde A_i$ of~$A_i$, the algorithm $((1+\varepsilon) \cdot a, b)$\=/approximates $\sum_i A_i$ in time $\Order(n \cdot \varepsilon^{-2} \log(\delta^{-1}))$, with probability at least $1 - \delta$ and for any parameters $a \geq 1$ and $b \geq 0$.
\itemdesc{Efficiency:} Sample $u \sim {\cal D}$. Then, for any $N \geq 1$ there is an event $E = E(u)$ happening with probability at least $1 - 1/N$, such that $\Ex_{u \sim \cal D}[\,1/u \mid E\,] \leq \widetilde{\Order}(\varepsilon^{-2} \log(\delta^{-1}) \log N)$.
\end{itemize}
\end{restatable}

\begin{restatable}[A Range Minimum Problem]{lemma}{lemrangeminimum} \label{lem:range-minimum}
There is an $\Order(K)$-time algorithm for the following problem: Given integers $A_{-K}, \dots, A_K$, compute for all $s \in \set{-K, \dots, K}$:
\begin{equation*}
    B_s = \min_{-K \leq s' \leq K} A_{s'} + 2 \cdot |s - s'|.
\end{equation*}
\end{restatable}

\begin{definition}[Block Periodicity]
Let $Y$ be a string. The \emph{$K$-block periodicity $\bp_K(Y)$} of~$Y$ is the smallest integer $L$ such that $Y$ can be partitioned into $Y = \bigcirc_{\ell=1}^L Y_\ell$, where each substring~$Y_\ell$ is $K$-periodic (i.e., $Y_\ell$ is periodic with period length at most $K$).
\end{definition}

\begin{restatable}[Periodic Rule]{lemma}{lemperiodicrule}\label{lem:periodicity-rule}
Let $Y$ be a string and write $Y_s = Y \range{K + s}{|Y| - K + s}$. If~$Y$ is periodic with primitive period $P$ and $|Y| \geq |P|^2 + 2K$, then for all~$s, s' \in \set{-K, \dots, K}$:
\begin{equation*}
    \ED(Y_s, Y_{s'}) = 2 \cdot \min_{j \in \Int} \big|\, s - s' + j|P| \,\big|.
\end{equation*}
\end{restatable}

\begin{restatable}[Random-Like Rule]{lemma}{lemrandomrule}\label{lem:random-rule}
Let $Y$ be a string and write $Y_s = Y \range{K + s}{|Y| - K + s}$. If $\bp_{4K}(Y) > 10K$, then for all~$s, s' \in \set{-K, \dots, K}$:
\begin{equation*}
    \ED(Y_s, Y_{s'}) = 2 \cdot |s - s'|.
\end{equation*}
\end{restatable}

\begin{restatable}[Intermediate]{lemma}{lemintermediate} \label{lem:intermediate-efficient}
Let $v$ be a node in the partition tree. Then, in any level in the subtree below $v$, for all but at most $2\bp_{4K}(Y_v)$ nodes $w$ the string $Y_w$ is $4K$-periodic.
\end{restatable}

\begin{restatable}[Periodicity Test]{lemma}{lemperiodicitytest} \label{lem:periodicity-test}
Let $X$ be a string, and let $r > 0$ be a sampling rate. There is an algorithm which returns one of the following two outputs:
\begin{itemize}
\item \Close[P], where $P$ is a primitive string of length $\leq K$ with $\HD(X, P^* \range{0}{|X|}) \leq 1/r$.
\item \Far, in which case $X$ is not $K$-periodic.
\end{itemize}
The algorithm runs in time~$\Order(r |X| \log(\delta^{-1}) + K)$ and is correct with probability $1 - \delta$.
\end{restatable}

\begin{restatable}[Matching Test]{lemma}{lemalignmenttest} \label{lem:alignment-test}
Let $X, Y$ be strings such that $|Y| = |X| + 2K$, and let $r > 0$ be a sampling rate. There is an algorithm which returns one of the following two outputs:
\begin{itemize}
\item \Close[s^*], where $s^* \in \set{-K, \dots, K}$ satisfies $\HD(X, Y \range{K + s^*}{|X| + K + s^*}) \leq 1/r$.
\item \Far, in which case there is no $s^* \in \set{-K, \dots, K}$ with $X = Y \range{K + s^*}{|X| + K + s^*}$.
\end{itemize}
The algorithm runs time $\Order(r |X| \log(\delta^{-1}) + K \log |X|)$ and is correct with probability $1 - \delta$.
\end{restatable}

